// Conecta BU -> agente de orientacion (RF-014, RN-011).
// El backend ya filtro crisis y preguntas clinicas; aqui se arma la consulta a Gemini
// con el contexto real que envia el backend (servicios, horarios y eventos).
const secreto = $env.CONECTA_BU_SECRET || '';
const cabeceras = $json.headers || {};
if (secreto && cabeceras['x-conecta-bu-secret'] !== secreto) {
  throw new Error('Peticion rechazada: secreto invalido.');
}

const { pregunta = '', usuario = {}, contexto = {}, reglas = '' } = $json.body || {};

const servicios = (contexto.servicios || []).map((s) => `- ${s.nombre}${s.descripcion ? ': ' + s.descripcion : ''}`).join('\n') || '- (sin servicios activos)';
const eventos = (contexto.eventos || []).map((e) => `- ${e.nombre} (${e.fecha}${e.lugar ? ', ' + e.lugar : ''})`).join('\n') || '- (sin eventos publicados)';

const instrucciones = [
  'Eres el asistente de orientación de Conecta BU, la plataforma de Bienestar Universitario (Desarrollo Humano / Orientación) de la Uniautónoma del Cauca.',
  reglas,
  'Responde en máximo 5 frases, en español de Colombia, con tono cálido y respetuoso.',
  'Solo usa la información de abajo; si no la tienes, dilo y sugiere agendar una cita o hablar con Bienestar.',
  'Cómo funciona la plataforma: «Agendar cita» para elegir un horario libre (solo una cita activa a la vez); «Mis citas» para consultar o cancelar (mínimo 24 horas antes); «Eventos» para inscribirse mientras haya cupos.',
  `Servicios activos:\n${servicios}`,
  `Horarios disponibles en este momento: ${contexto.horariosDisponibles ?? 'sin dato'}.`,
  `Próximos eventos:\n${eventos}`,
].filter(Boolean).join('\n\n');

return [{ json: {
  cuerpoGemini: {
    systemInstruction: { parts: [{ text: instrucciones }] },
    contents: [{ role: 'user', parts: [{ text: `${usuario.nombre ? 'Estudiante: ' + usuario.nombre + '. ' : ''}Pregunta: ${pregunta}` }] }],
    generationConfig: { temperature: 0.4, maxOutputTokens: 400 },
  },
} }];

// Toma el texto que devolvio Gemini y lo entrega con la forma que espera el backend: { respuesta }.
const partes = $json.candidates?.[0]?.content?.parts || [];
const respuesta = partes.map((p) => p.text || '').join('').trim();
if (!respuesta) {
  throw new Error('Gemini no devolvio texto.');
}
return [{ json: { respuesta } }];
